@Service
public class OrderService {

    private final OrderTransactions transactions; // a different bean, on purpose

    // Constructor injection: final fields, no container needed to build this
    // in a test, and nine parameters would look as wrong as they are.
    public OrderService(OrderTransactions transactions) {
        this.transactions = transactions;
    }

    public Order placeOrder(NewOrder request) {
        validate(request);
        // Through the proxy, so @Transactional actually applies.
        return transactions.persistAndCharge(request);
    }

    // WRONG - this is the bug we find most often:
    //
    //   public Order placeOrder(NewOrder r) { return this.persistAndCharge(r); }
    //
    //   @Transactional
    //   public Order persistAndCharge(NewOrder r) { ... }
    //
    // The internal call never leaves the object, so the proxy is bypassed and
    // there is no transaction. Nothing warns you; it just does not roll back.
}

@Component
class OrderTransactions {

    // rollbackFor because Spring commits on checked exceptions by default,
    // which surprises almost everyone who has not read that line.
    @Transactional(rollbackFor = Exception.class)
    public Order persistAndCharge(NewOrder request) throws PaymentException {
        Order order = repository.save(Order.from(request));
        gateway.charge(order.id(), order.amountMinor());
        return order;
    }
}

@Component
class OrderNotifications {
    // Not inside the transaction: an email sent for a rolled-back order
    // cannot be unsent.
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void onPlaced(OrderPlaced event) {
        mailer.sendConfirmation(event.orderId());
    }
}
